DO $stage03$
DECLARE p jsonb:=current_setting('ecr.stage03_plan',true)::jsonb;
 expected jsonb:=$plan${"schemaVersion":"ECRStage03OwnerActivation/1","status":"PROPOSED_NOT_ACTIVATED","taskId":"ARCHITECTURE-ECR-STAGE03-DURABLE-STORE-20261110","environment":"development","applicationId":"profitia-economic-calendar-runtime-development","componentId":"economic-calendar-runtime-development","role":"economic_calendar_development_ingest","organisationId":"225e465b-8b89-467d-92d1-7fef61b555fe","serviceId":"a80cf159-700a-4b5a-bd5a-8598113fa4e2","bindingId":"c713afb2-1668-4cd5-9b2e-8efe052edd6b","keyId":"ecr-source-service-20261106-v1","publicKeySha256":"27c6a456a3a64c1404b288af9da61946a7d04fd445fa2d18c02d081c4bfbeb3c","expiresAt":"2026-12-04T22:19:09.000Z","sourceQuotaMode":"UNMETERED","newServiceKey":false,"privateKeyPersistence":"OWNER_APPROVED_SECRET_STORE","identity":{"projectId":"spring-bread-28217539","branchId":"br-sparkling-term-b99l107x","databaseName":"platform_private","installMigration":"packages/platform-contracts/current-e1-authority/migrations/005-calendar-authority.sql","temporaryOperatorSetRole":{"operator":"neondb_owner","role":"profitia_access_owner","scope":"ONE_TRANSACTION_RESTORE_EXACT_MEMBERSHIPS_BEFORE_COMMIT"}},"store":{"projectId":"delicate-queen-44677134","sourceBranchId":"br-orange-salad-ba2llks7","newBranchName":"economic-calendar-development","initSource":"schema-only","copyData":false,"expiresAt":null,"databaseName":"economic_calendar_development","compute":{"minCU":0.25,"maxCU":0.5,"suspendAfterSeconds":300},"newProject":false,"roles":{"owner":"economic_calendar_development_owner","runtime":"economic_calendar_development_runtime","ingest":"economic_calendar_development_ingest","migrator":"economic_calendar_development_migrator"},"accessOwner":"profitia_access_owner","rolePrivileges":"NOINHERIT NOSUPERUSER NOBYPASSRLS NOCREATEDB NOCREATEROLE NOREPLICATION","migratorSetRoles":["profitia_access_owner","economic_calendar_development_owner"],"migrations":["packages/platform-contracts/migrations/access/001-internal-access.sql","packages/platform-contracts/current-e1-authority/migrations/002-receiver.sql","packages/platform-contracts/current-e1-authority/migrations/006-calendar-receiver.sql","apps/economic-calendar-runtime/migrations/001-read-model-and-preferences.sql","apps/economic-calendar-runtime/migrations/002-multi-source-calendar.sql"],"receiverProofKey":"NEW_32_RANDOM_BYTES_DATABASE_ONLY_PROTECTED_OPERATOR_FILE_NO_RUNTIME_ENV","newInfrastructureIds":"CAPTURE_ACTUAL_IDS_AFTER_APPROVED_CREATION_BEFORE_INSTALLATION"},"runtime":{"workspaceId":"tea-d7lps8rbc2fs73cn80dg","projectId":"prj-db717krrjlhs739jgo0g","environmentId":"evm-db717krrjlhs739jgo1g","name":"economic-calendar-runtime-development","origin":"https://economic-calendar-runtime-development.onrender.com","repo":"https://github.com/profitia/SG-dev","branch":"main","autoDeploy":"no","plan":"0.5c-512mb","region":"frankfurt","instances":1,"healthCheckPath":"/ready","newProject":false,"scheduler":false,"preview":false,"runtimeSecrets":["ECR_DATABASE_URL"],"operatorOnlySecrets":["ECR_INGEST_DATABASE_URL","ECR_MIGRATOR_DATABASE_URL","ECR_SOURCE_SIGNING_PRIVATE_KEY"],"providerSecrets":false,"renderComputeUSDPerMonth":7,"pricingReference":"https://render.com/pricing","neonCost":"Existing project usage billing; 0.25-0.5CU, suspend after300s; no plan upgrade, no provider paid calls"},"humanRead":{"userId":"092c2d9f-a84b-4c18-b3d6-e172a61399b8","product":"SPENDGURU","feature":"market","operation":"knowledge.read","resourceId":"economic-calendar-events","permissionGrantId":"4847951b-d962-4965-91e3-0bd03f0a675b","privatePreferenceGrants":false,"issuer":"https://unified-drum-7191.clerk.accounts.dev","authorizedParties":["https://dev-sg2.spendguru.app","https://economic-calendar-runtime-development.onrender.com"]},"grants":[{"grantId":"e7de5248-bfba-4a6c-b1c4-8bd987cab70c","provider":"eia","operation":"knowledge.read","feature":"market","resourceId":"api.eia.publication-calendar","licenceRef":"source-hub-eia-official-publication-schedules-2