HR_ACK_CLOSEOUT"]}$plan$::jsonb;
 decision text:=current_setting('ecr.stage03_owner_ref',true);
 b jsonb:=current_setting('ecr.stage03_binding',true)::jsonb;
 key_hex text:=current_setting('ecr.stage03_proof_key_hex',true);
 g jsonb; h jsonb; r record;
BEGIN
 IF current_user<>'profitia_access_owner' THEN RAISE EXCEPTION 'EXACT_E1_OWNER_REQUIRED'; END IF;
 IF p IS DISTINCT FROM expected OR coalesce(decision,'')!~'^owner-decision:sha256:[a-f0-9]{64}$'
 OR (p->>'expiresAt')::timestamptz<=clock_timestamp()+interval '10 minutes' THEN RAISE EXCEPTION 'EXACT_STAGE03_APPROVAL_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM profitia_access.installation WHERE singleton AND environment='development' AND project_id=p->'identity'->>'projectId' AND branch_id=p->'identity'->>'branchId' AND database_name=current_database())
 OR to_regprocedure('profitia_e1_authority.resource_allows(text,text,text)') IS NULL THEN RAISE EXCEPTION 'EXACT_CENTRAL_CALENDAR_INSTALLATION_REQUIRED'; END IF;
 IF b IS NULL OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(b) k) IS DISTINCT FROM ARRAY['applicationId','branchId','databaseName','environment','projectId','role','schemaDigest']
 OR b->>'applicationId' IS DISTINCT FROM p->>'applicationId' OR b->>'environment' IS DISTINCT FROM 'development' OR b->>'projectId' IS DISTINCT FROM p->'store'->>'projectId'
 OR coalesce(b->>'branchId','')!~'^br-[a-z0-9-]+$' OR b->>'branchId'=p->'store'->>'sourceBranchId' OR b->>'databaseName' IS DISTINCT FROM p->'store'->>'databaseName'
 OR b->>'role' IS DISTINCT FROM p->'store'->'roles'->>'runtime' OR coalesce(b->>'schemaDigest','')!~'^[a-f0-9]{64}$'
 OR coalesce(key_hex,'')!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'ACTUAL_ISOLATED_ECR_RECEIVER_BINDING_REQUIRED'; END IF;
 SELECT * INTO r FROM pg_roles WHERE rolname=p->>'role';
 IF NOT FOUND OR NOT r.rolcanlogin OR r.rolsuper OR r.rolbypassrls OR r.rolcreaterole OR r.rolcreatedb OR r.rolinherit OR r.rolreplication OR EXISTS(SELECT 1 FROM pg_auth_members WHERE member=r.oid) THEN RAISE EXCEPTION 'EXISTING_ORDINARY_ECR_SERVICE_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM profitia_access.applications WHERE application_id=p->>'applicationId' AND status='ACTIVE' AND fixed_organisation_id=(p->>'organisationId')::uuid)
 OR NOT EXISTS(SELECT 1 FROM profitia_access.runtime_bindings WHERE login_role=p->>'role' AND application_id=p->>'applicationId' AND status='ACTIVE')
 OR NOT EXISTS(SELECT 1 FROM profitia_services.runtime_bindings WHERE login_role=p->>'role' AND service_id=(p->>'serviceId')::uuid AND binding_id=(p->>'bindingId')::uuid AND status='ACTIVE' AND expires_at>=(p->>'expiresAt')::timestamptz)
 OR NOT EXISTS(SELECT 1 FROM profitia_e1_authority.source_components WHERE component_id=p->>'componentId' AND key_id=p->>'keyId' AND application_id=p->>'applicationId' AND login_role=p->>'role' AND receiver_application_id='profitia-source-hub-development' AND status='ACTIVE' AND expires_at>=(p->>'expiresAt')::timestamptz AND encode(public.digest(convert_to(public_key,'UTF8'),'sha256'),'hex')=p->>'publicKeySha256')
 OR NOT EXISTS(SELECT 1 FROM profitia_access.product_grants WHERE application_id='spendguru' AND organisation_id=(p->>'organisationId')::uuid AND product='SPENDGURU' AND 'market'=ANY(features) AND status='ACTIVE' AND expires_at>=(p->>'expiresAt')::timestamptz)
 THEN RAISE EXCEPTION 'CURRENT_ORIGINAL_ECR_COMPONENT_REQUIRED'; END IF;
 h:=p->'humanRead';
 IF NOT EXISTS(SELECT 1 FROM profitia_access.memberships WHERE user_id=(h->>'userId')::uuid AND organisation_id=(p->>'organisationId')::uuid AND status='ACTIVE' AND expires_at>=(p->>'expiresAt')::timestamptz)
 OR NOT EXISTS(SELECT 1 FROM profitia_access.external_identities WHERE user_id=(h->>'userId')::uuid AND issuer=h->>'issuer' AND status='ACTIVE' AND expires_at>=(p->>'expiresAt')::timestamptz)
 THEN RAISE EXCEPTION 'CURRENT_CANONICAL_READER_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM profitia_e1_authority.receivers WHERE application_id=p->>'applicationId') OR EXISTS(SELECT 1 FROM profitia_access.product_grants WHERE application_id=p->>'applicationId') OR EXISTS(SELECT 1 FROM profitia_access.permission_grants WHERE application_id=p->>'applicationId') THEN RAISE EXCEPTION 'ECR_RECEIVER_EXISTS_RECONCILE'; END IF;
 FOR g IN SELECT * FROM jsonb_array_elements(p->'grants') LOOP
 IF EXISTS(SELECT 1 FROM profitia_services.read_grants WHERE grant_id=(g->>'grantId')::uuid OR login_role=p->>'role' AND organisation_id=(p->>'organisationId')::uuid AND resource_id=g->>'resourceId') THEN RAISE EXCEPTION 'GRANT_EXISTS_RECONCILE'; END IF;
 INSERT INTO profitia_services.read_grants(grant_id,login_role,organisation_id,operation,feature,resource_id,effect,status,source_ref,expires_at) VALUES((g->>'grantId')::uuid,p->>'role',(p->>'organisationId')::uuid,g->>'operation',g->>'feature',g->>'resourceId','ALLOW','ACTIVE',decision,(p->>'expiresAt')::timestamptz);
 END LOOP;
 INSERT INTO profitia_access.product_grants(application_id,organisation_id,product,features,status,source,source_ref,expires_at) VALUES(p->>'applicationId',(p->>'organisationId')::uuid,'SPENDGURU',ARRAY['market'],'ACTIVE','EXPLICIT_OFFER',decision,(p->>'expiresAt')::timestamptz);
 INSERT INTO profitia_access.permission_grants(grant_id,application_id,organisation_id,user_id,effect,operation,feature,resource_id) VALUES((h->>'permissionGrantId')::uuid,p->>'applicationId',(p->>'organisationId')::uuid,(h->>'userId')::uuid,'ALLOW','knowledge.read','market','economic-calendar-events');
 INSERT INTO profitia_e1_authority.receivers(application_id,binding,issuer,authorized_parties,resource_id,key_id,proof_key,status,source_ref,expires_at) VALUES(p->>'applicationId',b,h->>'issuer',ARRAY(SELECT jsonb_array_elements_text(h->'authorizedParties')),'economic-calendar','ecr-product-receiver-stage03-v1',decode(key_hex,'hex'),'ACTIVE',decision,(p->>'expiresAt')::timestamptz);
END $stage03$;
